{
  "items": [
    {
      "title": "German Environment Agency (UBA) – Environmental Data Portal",
      "url_or_doi": "https://www.umweltbundesamt.de/en/data",
      "justification": "Official environmental data portal maintained by Germany's Federal Environment Agency (Umweltbundesamt). Provides datasets, environmental indicators, historical trends, and assessments covering air pollution, water quality, biodiversity, climate change, waste management, and natural resource conservation. Includes data from the 2020s and supports research into Germany's environmental conditions and conservation policies."
    },
    {
      "title": "Germany – Environmental Monitor 2024",
      "url_or_doi": "https://www.umweltbundesamt.de/en/publikationen/environmental-monitor-2024",
      "justification": "Published by the German Environment Agency in May 2024, this environmental monitoring resource covers 30 indicators related to Germany's environmental conditions and sustainability objectives. Topics include greenhouse gas emissions, biodiversity, land use, water quality, air pollution, renewable energy, and resource consumption. Particularly relevant for evaluating environmental progress during the early 2020s."
    },
    {
      "title": "Germany – Air Quality Open Data",
      "url_or_doi": "https://luftdaten.umweltbundesamt.de/index.php/en/air-quality-germany-open-data-everyone",
      "justification": "Official German air quality monitoring dataset providing hourly, daily, and annual measurements of particulate matter (PM10 and PM2.5), nitrogen dioxide (NO2), and ozone (O3). Data originate from monitoring stations across Germany's federal states and are accessible through downloadable records and APIs. Suitable for studying air pollution trends, environmental health, and the effects of emission reduction policies throughout the 2020s."
    },
    {
      "title": "Germany – Air Quality Trends, 2000–2024",
      "url_or_doi": "https://www.umweltbundesamt.de/themen/luft/daten-karten/entwicklung-der-luftqualitaet",
      "justification": "Environmental monitoring resource published by the German Environment Agency, documenting changes in major air pollutants across Germany from 2000 through 2024. Includes geographical visualizations and annual pollution indicators for particulate matter, nitrogen dioxide, and ozone. Useful for analyzing changes in air quality during 2020–2024 and comparing environmental conditions before and after 2020."
    },
    {
      "title": "Germany – Air Quality 2025",
      "url_or_doi": "https://www.umweltbundesamt.de/en/publikationen/luftqualitat-2025",
      "justification": "Official assessment of German air quality during 2025, published in February 2026. Uses preliminary monitoring data from federal and state air quality networks to evaluate particulate matter, nitrogen dioxide, and ozone concentrations. Provides information about pollution levels relative to European regulatory limits and World Health Organization recommendations, supporting research into recent environmental protection outcomes."
    },
    {
      "title": "Germany – Protected Landscape Areas",
      "url_or_doi": "https://data.europa.eu/data/datasets/8dceff1a-7bc1-4a49-9c08-a3f6b37f1b2b",
      "justification": "Geospatial dataset maintained by Germany's Federal Agency for Nature Conservation (Bundesamt für Naturschutz). Contains information about officially designated landscape protection areas throughout Germany. The dataset is harmonized from federal-state records and updated annually, making it particularly useful for studying habitat conservation, protected landscapes, land management, and conservation coverage during the 2020s."
    },
    {
      "title": "Germany – Federal Agency for Nature Conservation Protected Areas",
      "url_or_doi": "https://data.europa.eu/data/datasets/8b6394ba-749e-4d6e-94f5-7f1939b2a873",
      "justification": "Official geospatial dataset and Web Map Service covering protected natural areas throughout Germany. Includes national parks, nature reserves, biosphere reserves, nature parks, landscape protection areas, and Natura 2000 sites. Contains reference data from several years in the 2020s, including 2023 and 2025. Suitable for GIS analysis, biodiversity protection research, and assessments of Germany's conservation network."
    },
    {
      "title": "Germany – Environmental Indicators and Downloadable Data",
      "url_or_doi": "https://www.umweltbundesamt.de/en/data/environment-indicators/report",
      "justification": "Environmental indicator database operated by Germany's Federal Environment Agency. Provides access to downloadable environmental indicators and customizable reports covering air quality, particulate matter exposure, ecological conditions, and other environmental policy objectives. Useful for comparing environmental performance across the 2020s and evaluating progress toward sustainability targets."
    },
    {
      "title": "Germany – National Environmental and Nature Conservation Information Portal",
      "url_or_doi": "https://umwelt.info/en/",
      "justification": "National environmental information platform operated by the German Environment Agency. Aggregates environmental and nature conservation datasets from multiple German institutions and data providers. Relevant topics include biodiversity, ecosystem protection, pollution, natural resources, and environmental monitoring. Particularly useful for discovering datasets produced by German authorities during the 2020s."
    },
    {
      "title": "Germany – Environmental Data and Trends (Daten zur Umwelt)",
      "url_or_doi": "https://www.umweltbundesamt.de/daten",
      "justification": "German-language official environmental data platform offering access to datasets, thematic environmental maps, indicators, and environmental assessments. Covers climate change, energy, air pollution, water resources, agriculture, land use, ecosystems, and waste. Provides access to contemporary environmental monitoring resources suitable for studying Germany's environmental and conservation developments throughout the 2020s."
    },
    {
      "title": "Germany – Environmental Monitor 2020",
      "url_or_doi": "https://www.umweltbundesamt.de/sites/default/files/medien/376/publikationen/data-on-the-environment_environmental-monitor-2020.pdf",
      "justification": "Official 2020 environmental indicator report from the German Environment Agency. Provides baseline environmental statistics and references to downloadable indicator data covering biodiversity, air quality, climate change, land use, water quality, and other environmental issues. Useful for establishing environmental conditions at the beginning of the 2020s and comparing them with subsequent monitoring results."
    }
  ]
}
